'use strict';
const evaluation=document.getElementById('operational-review-panel');
async function loadReview(){let r=await get('operational-review.json');let m=r.metrics;evaluation.innerHTML='<span class="tag">EXPERIMENTAL</span><b>Em avaliação operacional · v0.2</b><p>'+r.history_counts.daily_discharged.toLocaleString('pt-PT')+' caudais médios diários recuperados no açude, 1987–2025. Ajuste preliminar em R: '+m.train_days+' dias de treino e '+m.validation_days+' de confronto; um fora do domínio.</p><p><b>Mancha atual por validar.</b> As peças batimétricas encontradas são históricas/de projeto. Não se publica risco atual de freguesia com base neste ajuste.</p>';}
